from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    flat=[x for r in g for x in r]
    bg=Counter(flat).most_common(1)[0][0]
    sep_rows=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg]
    sep_cols=[j for j in range(w) if len(set(g[i][j] for i in range(h)))==1 and g[0][j]!=bg]
    srows=[i for i in range(h) if i not in sep_rows]
    scols=[j for j in range(w) if j not in sep_cols]
    # find contiguous bands
    def bands(idx):
        out=[];cur=[idx[0]]
        for a in idx[1:]:
            if a==cur[-1]+1: cur.append(a)
            else: out.append(cur);cur=[a]
        out.append(cur);return out
    rb=bands(srows); cb=bands(scols)
    # block = cell region containing non-bg cells
    block=None
    for ri in rb:
        for ci in cb:
            if any(g[i][j]!=bg for i in ri for j in ci):
                block=(ri,ci)
    bri,bci=block
    out=[row[:] for row in g]
    for i in sep_rows:
        for j in range(w): out[i][j]=g[i][j]
    for ri in rb:
        for ci in cb:
            for k,i in enumerate(ri):
                for l,j in enumerate(ci):
                    out[i][j]=g[bri[k%len(bri)]][bci[l%len(bci)]]
    for j in sep_cols:
        for i in range(h): out[i][j]=g[i][j]
    return out

